// Mirrors backend `NotificationDto` (InvoiceTracker.Application/Notifications/Common) —
// System.Text.Json default camelCase serialization, same convention as every other DTO. Rows are
// entirely system-generated by the Kafka overdue-notification pipeline (`OverdueNotificationConsumer`)
// — there's no create/update/delete from the frontend, only a read-only list.
export interface Notification {
  id: string;
  invoiceId: string;
  /**
   * Denormalized display field populated by `ListNotificationsQueryHandler`'s join against
   * Invoices (GET /api/notifications), so the frontend doesn't need a separate per-row fetch of
   * the invoice just to show its number.
   */
  invoiceNumber?: string | null;
  status: "Pending" | "Sent" | "Failed";
  /** Set when the row transitions to `Sent`; stays `null` for `Pending`/`Failed`. */
  sentAt: string | null;
  channel: string;
  message: string;
  sourceEventId: string;
}
